$dir = new RecursiveDirectoryIterator('resources/views');
$iterator = new RecursiveIteratorIterator($dir);
$files = new RegexIterator($iterator, '/^.+\.blade\.php$/i', RecursiveRegexIterator::GET_MATCH);

foreach ($files as $file) {
    $path = $file[0];
    $content = file_get_contents($path);
    $changed = false;
    
    foreach ($replacements as $searchKey => $originalUrl) {
        $newContent = preg_replace('/https:\/\/placehold\.co[^"\']+' . preg_quote($searchKey, '/') . '[^"\']*/', $originalUrl, $content);
        if ($newContent !== $content) {
            $content = $newContent;
            $changed = true;
        }
    }
    
    if ($changed) {
        file_put_contents($path, $content);
        echo "Replaced placeholders with valid images in $path\n";
    }
}
